193→
194→  const { data: templates = [] } = useQuery({
195→    queryKey: ["email_templates"],
196→    queryFn: () => adminCall({ action: "get_templates" }),
197→  });
198→
199→  const { data: users = [] } = useQuery({
200→    queryKey: ["admin_users_email"],

200→    queryKey: ["admin_users_email"],
201→    queryFn: async () => {
202→      const { data: { session } } = await supabase.auth.getSession();
203→      const res = await supabase.functions.invoke("admin-users", {
204→        headers: { Authorization: `Bearer ${session?.access_token}` },
