247→
248→  // ─── Mutations ───
249→  const updateConfig = useMutation({
250→    mutationFn: (updates: Record<string, any>) => adminCall({ action: "update_config", updates }),
251→    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin_config"] }),
252→    onError: (e: any) => toast.error(e.message),
