254→
255→  const toggleOutbound = useMutation({
256→    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { outbound_email_enabled: enabled } }),
257→    onSuccess: () => { toast.success("Outbound email updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
258→    onError: (e: any) => toast.error(e.message),
259→  });
260→
261→  const toggleGlobal = useMutation({
262→    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { email_ingestion_enabled: enabled } }),
263→    onSuccess: () => { toast.success("Email ingestion updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
