266→
267→  const toggleNotification = useMutation({
268→    mutationFn: ({ field, enabled }: { field: string; enabled: boolean }) =>
269→      adminCall({ action: "update_config", updates: { [field]: enabled } }),
270→    onSuccess: () => { toast.success("Notification updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
271→    onError: (e: any) => toast.error(e.message),
272→  });
273→
274→  const saveResendConfig = useMutation({
275→    mutationFn: async () => {
276→      const updates: Record<string, any> = {
277→        email_from_address: fromAddress,
278→        email_from_name: fromName,
279→      };
