290→    },
291→    onError: (e: any) => toast.error(e.message),
292→  });
293→
294→  const updateTemplate = useMutation({
295→    mutationFn: ({ id, subject, body_html }: { id: string; subject: string; body_html: string }) =>
296→      adminCall({ action: "update_template", template_id: id, subject, body_html }),
297→    onSuccess: () => { toast.success("Template saved"); qc.invalidateQueries({ queryKey: ["email_templates"] }); },
298→    onError: (e: any) => toast.error(e.message),
299→  });
300→
301→  const toggleUser = useMutation({
302→    mutationFn: async ({ userId, enabled }: { userId: string; enabled: boolean }) => {
303→      const { data: { session } } = await supabase.auth.getSession();
304→      const res = await supabase.functions.invoke("admin-users", {
305→        method: "POST",
306→        headers: { Authorization: `Bearer ${session?.access_token}` },
307→        body: { user_id: userId, email_enabled: enabled },
308→      });
309→      if (res.error) throw res.error;
310→    },
311→    onSuccess: () => { toast.success("User email updated"); qc.invalidateQueries({ queryKey: ["admin_users_email"] }); },
312→    onError: (e: any) => toast.error(e.message),
313→  });
314→
315→  const handleSendTestEmail = async () => {
316→    if (!testEmailTo) { toast.error("Enter a recipient email"); return; }
317→    setSendingTest(true);
318→    try {
319→      const res = await supabase.functions.invoke("send-email", {
320→        body: {
321→          to: testEmailTo,
322→          template_key: "ranking_complete",
323→          variables: { user_name: "Admin", job_title: "Test Job", resume_count: "5", job_id: "test", app_url: window.location.origin },
324→        },
325→      });
326→      if (res.error) throw new Error(res.error.message);
327→      const data = res.data as any;
328→      if (data?.error) {
329→        toast.error(data.error);
330→      } else if (data?.skipped) {
331→        toast.error("Email skipped — check outbound is enabled");
332→      } else {
333→        toast.success(`Test email sent to ${testEmailTo}`);
334→      }
335→    } catch (e: any) { toast.error(e.message); }
336→    finally { setSendingTest(false); }
337→  };
338→
339→  const copyToClipboard = (text: string) => { navigator.clipboard.writeText(text); toast.success("Copied!"); };
340→
341→  const filtered = users.filter(
342→    (u) => u.email?.toLowerCase().includes(search.toLowerCase()) || u.inbox_email?.toLowerCase().includes(search.toLowerCase())
343→  );
344→
345→  const globalEnabled = config?.email_ingestion_enabled ?? true;
346→  const outboundEnabled = config?.outbound_email_enabled ?? false;
347→  const notifyRankingComplete = config?.email_notify_ranking_complete ?? true;
348→  const notifyResumeReceived = config?.email_notify_resume_received ?? true;
349→  const hasApiKey = !!config?.has_resend_key;
350→  const maskedKey = hasApiKey && !resendApiKey ? "***hidden***" : resendApiKey;
351→
352→  return (
353→    <div className="space-y-6">
354→      <div className="flex items-center justify-between">
355→        <div>
356→          <h2 className="text-xl font-semibold">Email Settings</h2>
357→          <p className="text-sm text-muted-foreground">Manage email sending, receiving, and templates</p>
358→        </div>
