360→          {hasApiKey && outboundEnabled ? <><CheckCircle2 className="h-3 w-3" /> Connected</> : <><AlertCircle className="h-3 w-3" /> Not Connected</>}
361→        </Badge>
362→      </div>
363→
364→      <Tabs defaultValue="connect" className="w-full">
365→        <TabsList className="grid w-full grid-cols-4 h-11">
366→          <TabsTrigger value="connect" className="gap-1.5"><Plug className="h-3.5 w-3.5" /> Connect</TabsTrigger>
