379→          {/* Email Provider */}
380→          <Card>
381→            <CardHeader className="pb-3">
382→              <CardTitle className="text-base flex items-center gap-2">
383→                <Key className="h-4 w-4" /> Email Provider
384→              </CardTitle>
385→            </CardHeader>
386→            <CardContent className="space-y-4">
387→              <div className="space-y-2">
388→                <Label className="text-sm font-medium">API Key</Label>
389→                <div className="flex gap-2">
390→                  <div className="relative flex-1">
391→                    <Input
392→                      type={showKey ? "text" : "password"}
393→                      placeholder="re_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
394→                      value={configLoaded ? maskedKey : ""}
395→                      onChange={(e) => setResendApiKey(e.target.value)}
396→                      className="font-mono text-sm pr-10"
397→                    />
398→                    <Button
399→                      type="button"
